  return [...new Set([...String(text ?? '').matchAll(CITE)].map((m) => m[1]))];
}

// Returns { draft, withheld, reasons, citations }. `draft` is null when withheld.
function checkDraft({ draft, citedIds, providedIds, injection, articleText }, opts = {}) {
  const enabled = opts.enabled !== false;
  const text = String(draft ?? '').trim();
  const inText = citationsIn(text);
  const cited = [...new Set([...(Array.isArray(citedIds) ? citedIds : []), ...inText])];
  if (!enabled) return { draft: text || null, withheld: !text, reasons: text ? [] : ['empty'], citations: cited };
  const reasons = [];
  if (!text) reasons.push('empty draft');
  if (injection) reasons.push('ticket contains instructions aimed at the AI');
  if (inText.length === 0) reasons.push('draft cites no help-center article');
  const provided = new Set(providedIds ?? []);
  const unknown = cited.filter((id) => !provided.has(id));
  if (unknown.length) reasons.push(`cites articles that were not provided: ${unknown.join(', ')}`);
  // Only text of articles that are both provided and cited may be quoted.
  const quotable = unknown.length ? '' : cited.map((id) => (articleText ?? {})[id] ?? '').join('\n');
  const promises = findPromises(text, quotable);
  if (promises.length) reasons.push(`promises only Billing or Engineering can make: ${promises.join(', ')}`);
  return reasons.length ? { draft: null, withheld: true, reasons, citations: cited } : { draft: text, withheld: false, reasons: [], citations: inText };
}

// Builds the model input from the fetched Zendesk + Stripe records. Plain JS; build.mjs inlines it
// together with policy.js and guardrail.js.

function prepareContext({ ticket, user, organization, customer, articles }) {
  const tier = normalizeTier(customer?.metadata?.plan);
  const mrrCents = Number(customer?.metadata?.mrr_cents ?? 0);
  const name = String(user?.name ?? '').trim();
  const list = (articles ?? []).map((a) => ({ id: a.id, title: a.title, body: a.body }));
  const text = customerText(ticket);
  const articleText = list.map((a) => `[${a.id}] ${a.title}\n${a.body}`).join('\n\n');
  // The ticket is wrapped as data. Angle brackets are escaped so a ticket can't close the tag early.
  const esc = (s) => String(s ?? '').replace(/</g, '‹').replace(/>/g, '›');
  const modelInput = [
    `<account>\nCompany: ${organization?.name ?? 'unknown'}\nPlan: ${tier}\nRequester: ${name || 'unknown'}\n</account>`,
    `<help_center_articles>\n${articleText}\n</help_center_articles>`,
    `<ticket id="${ticket?.id}">\nSubject: ${esc(ticket?.subject)}\n\n${esc(ticket?.description)}\n</ticket>`,
  ].join('\n\n');
  return {
    ticket_id: ticket?.id, subject: ticket?.subject ?? '', created_at: ticket?.created_at,
    requester_name: name, requester_first: name.split(/\s+/)[0] ?? '', org_name: organization?.name ?? '',
    tier, mrr_cents: mrrCents, article_ids: list.map((a) => a.id), article_text: Object.fromEntries(list.map((a) => [a.id, a.body])), text,
    injection: detectInjection(text), model_input: modelInput,
  };
}

// ---- n8n wrapper ----
const ctx = prepareContext({
  ticket: $('Zendesk: get ticket').first().json.ticket,
  user: $('Zendesk: get requester').first().json.user,
  organization: $('Zendesk: get organization').first().json.organization,
  customer: $('Stripe: get customer (plan, MRR)').first().json,
  articles: $('Zendesk Guide: help-center articles').first().json.articles,
});
return [{ json: ctx }];

